mapper.select:
SELECT COUNT(*)
FROM NOTIFICATIONS
WHERE receiverId = #{receiverId}
  AND notifyType = #{notifyType}
  AND content = #{content}
  AND regDt >= DATE_SUB(NOW(), INTERVAL #{withinMinutes} MINUTE)

mapper.delete:
DELETE FROM NOTIFICATIONS WHERE notifyType IN
#{type}
AND regDt < DATE_SUB(NOW(), INTERVAL #{keepDays} DAY)
